function designTabLabel(name) {
  return String(name ?? "design").replace(/\.html$/i, "");
}
function nodeSelectedMessageOk(message) {
  return (
    !!message &&
    message.source === "canvas-design-harness" &&
    message.type === "node:selected" &&
    !!message.payload &&
    typeof message.payload === "object" &&
    (typeof message.payload.nodeId === "string" || message.payload.nodeId === null)
  );
}

